/**
 * KalshiPaperSim — Official Kalshi Request Signing (Node.js only)
 * =====================================================================
 * Implements EXACTLY the algorithm published by Kalshi:
 *   https://docs.kalshi.com/getting_started/api_keys
 *
 * Quoted from the docs:
 *   "The above signature is generated by signing a concatenation of the
 *    timestamp, the HTTP method and the path."
 *   "Important: When signing requests, use the path WITHOUT query parameters."
 *   headers: KALSHI-ACCESS-KEY / KALSHI-ACCESS-TIMESTAMP / KALSHI-ACCESS-SIGNATURE
 *
 * Kalshi's own JavaScript sample (quoted verbatim from the docs):
 *   function signPssText(privateKeyPem, text) {
 *     const sign = crypto.createSign('RSA-SHA256');
 *     sign.update(text); sign.end();
 *     const signature = sign.sign({
 *       key: privateKeyPem,
 *       padding: crypto.constants.RSA_PKCS1_PSS_PADDING,
 *       saltLength: crypto.constants.RSA_PSS_SALTLEN_DIGEST,
 *     });
 *     return signature.toString('base64');
 *   }
 *
 * WebSocket handshake signing (https://docs.kalshi.com/getting_started/quick_start_websockets):
 *   message to sign = timestamp + "GET" + "/trade-api/ws/v2"
 *
 * SECURITY: this module is imported ONLY by server-side code (server.js).
 * Private keys must be supplied via environment variables and are never
 * written to the repository, the browser, or any log.
 */

import crypto from 'node:crypto';
import fs from 'node:fs';
import { KALSHI_AUTH, WS_SIGN_PATH } from './kalshi-config.js';

/**
 * Sign text with an RSA private key using RSA-PSS / SHA-256 / salt=digest length.
 * @param {string} privateKeyPem PEM-encoded RSA private key
 * @param {string} text          timestamp + METHOD + path
 * @returns {string} base64 signature
 */
export function signPssText(privateKeyPem, text) {
  const sign = crypto.createSign('RSA-SHA256');
  sign.update(text);
  sign.end();
  const signature = sign.sign({
    key: privateKeyPem,
    padding: crypto.constants.RSA_PKCS1_PSS_PADDING,
    saltLength: crypto.constants.RSA_PSS_SALTLEN_DIGEST
  });
  return signature.toString('base64');
}

/** Strip the query string before signing (docs requirement). */
export function signingPath(fullPath) {
  return String(fullPath).split('?')[0];
}

/**
 * Build the three Kalshi auth headers for a REST request.
 * @param {object} args
 * @param {string} args.keyId       KALSHI-ACCESS-KEY value (the Key ID)
 * @param {string} args.privateKeyPem
 * @param {string} args.method      e.g. 'GET'
 * @param {string} args.path        e.g. '/trade-api/v2/portfolio/balance?limit=5'
 * @param {number} [args.timestampMs] override for deterministic tests
 * @returns {{headers:object, messageSigned:string, timestamp:string}}
 */
export function buildAuthHeaders({ keyId, privateKeyPem, method = 'GET', path, timestampMs = Date.now() }) {
  const timestamp = String(timestampMs);
  const pathWithoutQuery = signingPath(path);
  const messageSigned = timestamp + method.toUpperCase() + pathWithoutQuery;
  const signature = signPssText(privateKeyPem, messageSigned);
  return {
    headers: {
      [KALSHI_AUTH.headerKey]: keyId,
      [KALSHI_AUTH.headerSignature]: signature,
      [KALSHI_AUTH.headerTimestamp]: timestamp
    },
    messageSigned,
    timestamp
  };
}

/**
 * Build the auth headers for the WebSocket handshake.
 * Message signed = timestamp + "GET" + "/trade-api/ws/v2"
 */
export function buildWsAuthHeaders({ keyId, privateKeyPem, timestampMs = Date.now() }) {
  return buildAuthHeaders({ keyId, privateKeyPem, method: 'GET', path: WS_SIGN_PATH, timestampMs });
}

/** Read credentials from the environment (never from the repo or the browser). */
export function credentialsFromEnv(env = process.env) {
  const keyId = env.KALSHI_API_KEY_ID || env.KALSHI_ACCESS_KEY || null;
  const privateKeyPem =
    env.KALSHI_API_PRIVATE_KEY ||
    (env.KALSHI_API_PRIVATE_KEY_PATH ? readKeyFile(env.KALSHI_API_PRIVATE_KEY_PATH) : null);
  return {
    configured: Boolean(keyId && privateKeyPem),
    keyId,
    privateKeyPem,
    environment: env.KALSHI_ENV === 'demo' ? 'demo' : 'production'
  };
}

function readKeyFile(p) {
  try {
    return fs.readFileSync(p, 'utf8');
  } catch {
    return null;
  }
}
